const fs = require('fs');
const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
let idx = 0;
const N = data[idx++];
const dice = [];
for (let i = 0; i < N; i++) {
    const faces = data.slice(idx, idx + 6);
    idx += 6;
    dice.push(faces);
}

function getOppAndSideMax(faces) {
    const opp = new Array(7);
    const sideMax = new Array(7);
    opp[faces[0]] = faces[5];
    opp[faces[5]] = faces[0];
    opp[faces[1]] = faces[3];
    opp[faces[3]] = faces[1];
    opp[faces[2]] = faces[4];
    opp[faces[4]] = faces[2];

    for (let b = 1; b <= 6; b++) {
        const t = opp[b];
        let maxVal = 0;
        for (let v = 1; v <= 6; v++) {
            if (v !== b && v !== t) {
                if (v > maxVal) maxVal = v;
            }
        }
        sideMax[b] = maxVal;
    }
    return { opp, sideMax };
}

let dp = new Array(7).fill(-Infinity);
const first = getOppAndSideMax(dice[0]);
for (let b = 1; b <= 6; b++) {
    const t = first.opp[b];
    dp[t] = Math.max(dp[t], first.sideMax[b]);
}

for (let i = 1; i < N; i++) {
    const { opp, sideMax } = getOppAndSideMax(dice[i]);
    const newdp = new Array(7).fill(-Infinity);
    for (let p = 1; p <= 6; p++) {
        if (dp[p] === -Infinity) continue;
        const b = p;
        const t = opp[b];
        newdp[t] = Math.max(newdp[t], dp[p] + sideMax[b]);
    }
    dp = newdp;
}

let ans = 0;
for (let t = 1; t <= 6; t++) {
    if (dp[t] > ans) ans = dp[t];
}
console.log(ans);
